import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const lastScanRef = useRef(null);

  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  useEffect(() => {
    const startScanner = async () => {
      const scanner = new Html5Qrcode("reader");
      scannerRef.current = scanner;

      try {
        await scanner.start(
          { facingMode: "environment" },
          {
            fps: 20,
            qrbox: { width: 250, height: 250 },
          },

          async (decodedText) => {
            if (lastScanRef.current === decodedText) return;
            lastScanRef.current = decodedText;

            console.log("QR Detected:", decodedText);

            try {
              const verify = await fetch(
                `http://localhost:5000/verify-user/${decodedText}`,
              );

              const verifyData = await verify.json();

              if (!verifyData.success) {
                setStatus("notfound");
                return;
              }

              setStudent(verifyData.user);

              const attendance = await fetch(
                `http://localhost:5000/mark-attendance/${decodedText}`,
                { method: "PUT" },
              );

              const attendanceData = await attendance.json();

              if (attendanceData.success) {
                setStatus("success");
              } else {
                setStatus("already");
              }
            } catch (error) {
              console.log(error);
              setStatus("servererror");
            }

            setTimeout(() => {
              lastScanRef.current = null;
            }, 2000);
          },
        );
      } catch (err) {
        console.log("Scanner error:", err);
      }
    };

    startScanner();

    return () => {
      if (scannerRef.current) {
        scannerRef.current
          .stop()
          .then(() => scannerRef.current.clear())
          .catch(() => {});
      }
    };
  }, []);

  return (
    <div style={{ textAlign: "center", marginTop: "40px" }}>
      <h2>QR Attendance Scanner</h2>

      <div
        id="reader"
        style={{
          width: "350px",
          margin: "auto",
          border: "3px solid black",
        }}
      ></div>

      {student && (
        <div style={{ marginTop: "20px" }}>
          <h3>{student.name}</h3>
          <p>{student.college_name}</p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>Already Scanned</h2>
          )}
        </div>
      )}
    </div>
  );
}

export default QRScanner;
